                    left = Node("between", negated, (left, low, high))
                else:
                    left = Node("like", negated, (left, self.parse_additive()))
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            if op == "||":
                left = Node("concat", None, (left, right))
            else:
                left = Node("arith", op, (left, right))
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = Node("arith", op, (left, self.parse_unary()))
        return left

    def parse_unary(self):
        if self.accept_op("-"):
            return Node("neg", None, (self.parse_unary(),))
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok.kind in ("num", "str"):
            self.advance()
            return literal(tok.value)
        if tok.kind == "kw" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return literal({"NULL": None, "TRUE": True, "FALSE": False}[tok.value])
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        if tok.kind == "name" and self.peek(1) == ("op", "(", self.peek(1).start, self.peek(1).end):
            return self.parse_call()
        if tok.kind in ("name", "qname"):
            self.advance()
            return Node("name", tok.value, ())
        self.error("expected an expression")

    def parse_call(self):
        tok = self.advance()
        name = tok.value.upper()
        self.advance()  # "("
        if name not in AGGREGATES and name not in FUNCTION_ARITY:
            raise QueryError(f"unknown function {tok.value}")
        if name == "COUNT" and self.accept_op("*"):
            self.expect_op(")")
            return Node("agg", name, ())
        args = [] if self.at_op(")") else self.comma_list(self.parse_expr)
        self.expect_op(")")
        if name in AGGREGATES:
            low = high = 1
        else:
            low, high = FUNCTION_ARITY[name]
        if len(args) < low or (high is not None and len(args) > high):
            raise QueryError(f"wrong number of arguments to {tok.value}: {len(args)}")
        return Node("agg" if name in AGGREGATES else "func", name, tuple(args))

