"""Tokenizer and recursive-descent parser for minisql queries.

Expressions are parsed into ``Node`` tuples of ``(kind, info, args)``, where
``args`` is a tuple of child nodes. Nodes compare and hash structurally, which
the engine uses to match select expressions against GROUP BY expressions.

Node kinds:

    lit      info=(type name, value)
    name     info=column name as written (resolved to ``col`` by the engine)
    col      info=column index
    neg      args=(x,)
    arith    info='+' | '-' | '*' | '/', args=(a, b)
    concat   args=(a, b)
    cmp      info='=' | '!=' | '<' | '<=' | '>' | '>=', args=(a, b)
    isnull   info=negated, args=(x,)
    in       info=negated, args=(x, item, ...)
    between  info=negated, args=(x, low, high)
    like     info=negated, args=(x, pattern)
    not      args=(x,)
    and, or  args=(a, b)
    func     info=upper-case name, args=arguments
    agg      info=upper-case name, args=(x,), or () for COUNT(*)
"""

import re
from collections import namedtuple

from ._errors import QueryError

Node = namedtuple("Node", "kind info args")

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

AGGREGATES = frozenset(["COUNT", "SUM", "AVG", "MIN", "MAX"])

# Scalar function name -> (minimum, maximum) argument count; None is unbounded.
FUNCTION_ARITY = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_COMPARISONS = {"=": "=", "!=": "!=", "<>": "!=", "<": "<", "<=": "<=", ">": ">", ">=": ">="}
_TWO_CHAR_OPS = frozenset(["<=", ">=", "<>", "!=", "||"])
_ONE_CHAR_OPS = frozenset("=<>+-*/(),;")
_DIGITS = frozenset("0123456789")
_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]*)?|\.[0-9]+")

Query = namedtuple(
    "Query", "distinct columns table where group_by having order_by limit offset"
)
# ``bare_name`` is the name when the expression is a single name token.
Column = namedtuple("Column", "expr text alias bare_name")
# ``position`` is the integer when the expression is a single integer token.
OrderItem = namedtuple("OrderItem", "expr desc bare_name position")


class Token(namedtuple("Token", "kind value start end")):
    """A token; ``kind`` is num, str, name, qname, kw, op, or eof."""


def literal(value):
    return Node("lit", (type(value).__name__, value), ())


def tokenize(sql):
    tokens = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if c == "'":
            value, i = _quoted(sql, i, "string")
            tokens.append(Token("str", value, start, i))
        elif c == '"':
            value, i = _quoted(sql, i, "name")
            if not value:
                raise QueryError(f"empty quoted name at position {start + 1}")
            tokens.append(Token("qname", value, start, i))
        elif c in _DIGITS or (c == "." and sql[i + 1 : i + 2] in _DIGITS and i + 1 < n):
            text = _NUMBER_RE.match(sql, i).group()
            i += len(text)
            if i < n and (sql[i].isalnum() or sql[i] in "_."):
                raise QueryError(f"invalid number at position {start + 1}")
            value = float(text) if "." in text else int(text)
            tokens.append(Token("num", value, start, i))
        elif c.isalpha() or c == "_":
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == "_"):
                i += 1
            word = sql[start:i]
            upper = word.upper() if word.isascii() else None
            if upper in KEYWORDS:
                tokens.append(Token("kw", upper, start, i))
            else:
                tokens.append(Token("name", word, start, i))
        elif sql[i : i + 2] in _TWO_CHAR_OPS:
            i += 2
            tokens.append(Token("op", sql[start:i], start, i))
        elif c in _ONE_CHAR_OPS:
            i += 1
            tokens.append(Token("op", c, start, i))
        else:
            raise QueryError(f"unexpected character {c!r} at position {start + 1}")
    tokens.append(Token("eof", None, n, n))
    return tokens


def _quoted(sql, i, what):
    """Read text quoted by ``sql[i]``, where a doubled quote stands for one."""
    quote = sql[i]
    parts = []
    j = i + 1
    while True:
        k = sql.find(quote, j)
        if k < 0:
            raise QueryError(f"unterminated {what} at position {i + 1}")
        parts.append(sql[j:k])
        if sql[k + 1 : k + 2] == quote:
            parts.append(quote)
            j = k + 2
        else:
            return "".join(parts), k + 1


def parse(sql):
    return _Parser(sql).parse_query()


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- token helpers -----------------------------------------------------

    def peek(self, offset=0):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self):
        tok = self.tokens[self.pos]
        if tok.kind != "eof":
            self.pos += 1
        return tok

    def at_kw(self, *words, offset=0):
        tok = self.peek(offset)
        return tok.kind == "kw" and tok.value in words

    def accept_kw(self, word):
        if self.at_kw(word):
            return self.advance()
        return None

    def expect_kw(self, word):
        if not self.accept_kw(word):
            self.error(f"expected {word}")

    def at_op(self, *ops):
        tok = self.peek()
        return tok.kind == "op" and tok.value in ops

    def accept_op(self, op):
        if self.at_op(op):
            return self.advance()
        return None

    def expect_op(self, op):
        if not self.accept_op(op):
            self.error(f"expected '{op}'")

    def expect_name(self, what):
        tok = self.peek()
        if tok.kind not in ("name", "qname"):
            self.error(f"expected {what}")
        return self.advance().value

    def expect_integer(self, what):
        tok = self.peek()
        if tok.kind != "num" or not isinstance(tok.value, int):
            self.error(f"expected {what}")
        return self.advance().value

    def error(self, message):
        tok = self.peek()
        if tok.kind == "eof":
            found = "end of query"
        else:
            found = f"{self.sql[tok.start:tok.end]!r} at position {tok.start + 1}"
        raise QueryError(f"syntax error: {message}, found {found}")

    def comma_list(self, parse_item):
        items = [parse_item()]
        while self.accept_op(","):
            items.append(parse_item())
        return items

    # -- clauses -----------------------------------------------------------

    def parse_query(self):
        self.expect_kw("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))
        if self.accept_op("*"):
            columns = None
        else:
            columns = self.comma_list(self.parse_column)
        self.expect_kw("FROM")
        table = self.expect_name("table name")
        where = self.parse_expr() if self.accept_kw("WHERE") else None
        group_by = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by = self.comma_list(self.parse_expr)
        having = self.parse_expr() if self.accept_kw("HAVING") else None
        order_by = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by = self.comma_list(self.parse_order_item)
        limit = offset = None
        if self.accept_kw("LIMIT"):
            limit = self.expect_integer("integer after LIMIT")
            if self.accept_kw("OFFSET"):
                offset = self.expect_integer("integer after OFFSET")
        self.accept_op(";")
        if self.peek().kind != "eof":
            self.error("expected end of query")
        return Query(distinct, columns, table, where, group_by, having, order_by, limit, offset)

    def parse_column(self):
        start = self.pos
        expr = self.parse_expr()
        first, last = self.tokens[start], self.tokens[self.pos - 1]
        text = self.sql[first.start : last.end]
        bare_name = first.value if self.pos - start == 1 and first.kind in ("name", "qname") else None
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name("column alias after AS")
        elif self.peek().kind in ("name", "qname"):
            alias = self.advance().value
        return Column(expr, text, alias, bare_name)

    def parse_order_item(self):
        start = self.pos
        expr = self.parse_expr()
        first = self.tokens[start]
        bare_name = position = None
        if self.pos - start == 1:
            if first.kind in ("name", "qname"):
                bare_name = first.value
            elif first.kind == "num" and isinstance(first.value, int):
                position = first.value
        desc = False
        if self.accept_kw("DESC"):
            desc = True
        else:
            self.accept_kw("ASC")
        return OrderItem(expr, desc, bare_name, position)

    # -- expressions, lowest precedence first ------------------------------

    def parse_expr(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = Node("or", None, (left, self.parse_and()))
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = Node("and", None, (left, self.parse_not()))
        return left

    def parse_not(self):
        if self.accept_kw("NOT"):
            return Node("not", None, (self.parse_not(),))
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        while True:
            tok = self.peek()
            if tok.kind == "op" and tok.value in _COMPARISONS:
                self.advance()
                left = Node("cmp", _COMPARISONS[tok.value], (left, self.parse_additive()))
            elif self.accept_kw("IS"):
                negated = bool(self.accept_kw("NOT"))
                self.expect_kw("NULL")
                left = Node("isnull", negated, (left,))
            elif self.at_kw("IN", "BETWEEN", "LIKE") or (
                self.at_kw("NOT") and self.at_kw("IN", "BETWEEN", "LIKE", offset=1)
            ):
                negated = bool(self.accept_kw("NOT"))
                word = self.advance().value
                if word == "IN":
                    self.expect_op("(")
                    items = self.comma_list(self.parse_expr)
                    self.expect_op(")")
                    left = Node("in", negated, (left, *items))
                elif word == "BETWEEN":
                    low = self.parse_additive()
                    self.expect_kw("AND")
                    high = self.parse_additive()
                    left = Node("between", negated, (left, low, high))
                else:
                    left = Node("like", negated, (left, self.parse_additive()))
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            if op == "||":
                left = Node("concat", None, (left, right))
            else:
                left = Node("arith", op, (left, right))
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            left = Node("arith", op, (left, self.parse_unary()))
        return left

    def parse_unary(self):
        if self.accept_op("-"):
            return Node("neg", None, (self.parse_unary(),))
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok.kind in ("num", "str"):
            self.advance()
            return literal(tok.value)
        if tok.kind == "kw" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            return literal({"NULL": None, "TRUE": True, "FALSE": False}[tok.value])
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        if tok.kind == "name" and self.peek(1) == ("op", "(", self.peek(1).start, self.peek(1).end):
            return self.parse_call()
        if tok.kind in ("name", "qname"):
            self.advance()
            return Node("name", tok.value, ())
        self.error("expected an expression")

    def parse_call(self):
        tok = self.advance()
        name = tok.value.upper()
        self.advance()  # "("
        if name not in AGGREGATES and name not in FUNCTION_ARITY:
            raise QueryError(f"unknown function {tok.value}")
        if name == "COUNT" and self.accept_op("*"):
            self.expect_op(")")
            return Node("agg", name, ())
        args = [] if self.at_op(")") else self.comma_list(self.parse_expr)
        self.expect_op(")")
        if name in AGGREGATES:
            low = high = 1
        else:
            low, high = FUNCTION_ARITY[name]
        if len(args) < low or (high is not None and len(args) > high):
            raise QueryError(f"wrong number of arguments to {tok.value}: {len(args)}")
        return Node("agg" if name in AGGREGATES else "func", name, tuple(args))

