"""Table loading, expression evaluation, and query execution."""

import csv
import math
import operator
import os
import re
from decimal import ROUND_HALF_UP, Decimal, localcontext

from ._errors import QueryError
from ._parser import Node

_INTEGER_RE = re.compile(r"-?[0-9]+")
_DECIMAL_RE = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)")


class Result:
    """The result of a query: output column names and rows of values."""

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return f"Result(columns={self.columns!r}, rows={self.rows!r})"


# -- tables -----------------------------------------------------------------


def _convert(field):
    if field == "":
        return None
    if _INTEGER_RE.fullmatch(field):
        return int(field)
    if _DECIMAL_RE.fullmatch(field):
        return float(field)
    return field


def load_table(directory, name):
    """Return ``(header, rows)`` for ``name.csv`` in ``directory``."""
    if name in (".", "..") or any(c in name for c in "/\\\0"):
        raise QueryError(f"invalid table name {name!r}")
    filename = name + ".csv"
    path = os.path.join(directory, filename)
    if not os.path.isfile(path):
        # Fall back to a case-insensitive match, as names are case-insensitive.
        try:
            matches = [f for f in os.listdir(directory) if f.lower() == filename.lower()]
        except OSError:
            matches = []
        if len(matches) != 1 or not os.path.isfile(os.path.join(directory, matches[0])):
            raise QueryError(f"no such table: {name}")
        path = os.path.join(directory, matches[0])
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if not header:
                raise QueryError(f"table {name} has no header line")
            rows = []
            for record in reader:
                if not record:
                    continue
                if len(record) != len(header):
                    raise QueryError(
                        f"{filename} line {reader.line_num}: expected {len(header)} "
                        f"fields, found {len(record)}"
                    )
                rows.append(tuple(map(_convert, record)))
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError(f"cannot read table {name}: {e}") from None
    return header, rows


# -- values -----------------------------------------------------------------


def _kind(value):
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    return "string"


def _is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def _group_key(value):
    """A hashable key under which values are equal exactly when SQL says so."""
    if value is None:
        return None
    return (_kind(value), value)


def _truth(value, clause):
    if value is None or isinstance(value, bool):
        return value is True
    raise QueryError(f"{clause} condition must be a boolean, not a {_kind(value)}")


def _check_number(value, what):
    if not _is_number(value):
        raise QueryError(f"{what} expects numbers, not a {_kind(value)}")


def _check_string(value, what):
    if not isinstance(value, str):
        raise QueryError(f"{what} expects a string, not a {_kind(value)}")


def _check_boolean(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError(f"{what} expects booleans, not a {_kind(value)}")


# -- operators --------------------------------------------------------------

_ARITH_OPS = {"+": operator.add, "-": operator.sub, "*": operator.mul, "/": operator.truediv}
_COMPARE_OPS = {
    "=": operator.eq,
    "!=": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


def _arith(op, a, b):
    if a is None or b is None:
        return None
    _check_number(a, f"'{op}'")
    _check_number(b, f"'{op}'")
    if op == "/" and b == 0:
        return None
    try:
        return _ARITH_OPS[op](a, b)
    except OverflowError:
        raise QueryError(f"numeric overflow in '{op}'") from None


def _negate(value):
    if value is None:
        return None
    _check_number(value, "unary '-'")
    return -value


def _concat(a, b):
    if a is None or b is None:
        return None
    return _text(a) + _text(b)


def _compare(op, a, b):
    if a is None or b is None:
        return None
    if _kind(a) != _kind(b):
        raise QueryError(f"cannot compare a {_kind(a)} with a {_kind(b)}")
    return _COMPARE_OPS[op](a, b)


def _not(value):
    _check_boolean(value, "NOT")
    return None if value is None else not value


def _and(a, b):
    _check_boolean(a, "AND")
    _check_boolean(b, "AND")
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _in(value, items):
    if value is None:
        return None
    saw_null = False
    for item in items:
        equal = _compare("=", value, item)
        if equal:
            return True
        if equal is None:
            saw_null = True
    return None if saw_null else False


def _like(value, pattern):
    if value is None or pattern is None:
        return None
    _check_string(value, "LIKE")
    _check_string(pattern, "LIKE")
    # Wildcard matching that backtracks only to the most recent '%'.
    i = j = 0
    star = -1
    mark = 0
    while i < len(value):
        if j < len(pattern) and pattern[j] == "%":
            star, mark = j, i
            j += 1
        elif j < len(pattern) and pattern[j] in ("_", value[i]):
            i += 1
            j += 1
        elif star >= 0:
            mark += 1
            i, j = mark, star + 1
        else:
            return False
    while j < len(pattern) and pattern[j] == "%":
        j += 1
    return j == len(pattern)


# -- scalar functions -------------------------------------------------------


def _lower(s):
    if s is None:
        return None
    _check_string(s, "LOWER")
    return s.lower()


def _upper(s):
    if s is None:
        return None
    _check_string(s, "UPPER")
    return s.upper()


def _length(s):
    if s is None:
        return None
    _check_string(s, "LENGTH")
    return len(s)


def _abs(x):
    if x is None:
        return None
    _check_number(x, "ABS")
    return abs(x)


def _round(x, places=0, to_integer=True):
    if x is None or places is None:
        return None
    _check_number(x, "ROUND")
    if not to_integer and not (isinstance(places, int) and not isinstance(places, bool)):
        raise QueryError(f"ROUND expects an integer number of places, not {_text(places)}")
    if isinstance(x, float) and not math.isfinite(x):
        if to_integer:
            raise QueryError(f"cannot round {x} to an integer")
        return x
    if to_integer:
        if isinstance(x, int):
            return x
        return int(Decimal(repr(x)).to_integral_value(rounding=ROUND_HALF_UP))
    # Floats have under 400 significant places on either side of the point,
    # so clamping keeps the result exact while bounding the work.
    places = max(-400, min(400, places))
    with localcontext() as ctx:
        ctx.prec = 2000
        d = Decimal(repr(x)) if isinstance(x, float) else Decimal(x)
        rounded = d.scaleb(places).to_integral_value(rounding=ROUND_HALF_UP).scaleb(-places)
    result = float(rounded)
    if math.isinf(result):
        raise QueryError("numeric overflow in ROUND")
    return result + 0.0  # turns -0.0 into 0.0


def _round_call(*args):
    if len(args) == 1:
        return _round(args[0])
    return _round(args[0], args[1], to_integer=False)


_FUNCTIONS = {
    "LOWER": _lower,
    "UPPER": _upper,
    "LENGTH": _length,
    "ABS": _abs,
    "ROUND": _round_call,
}


# -- aggregates -------------------------------------------------------------


def _aggregate(name, arg, rows):
    if arg is None:  # COUNT(*)
        return len(rows)
    values = [v for v in map(arg, rows) if v is not None]
    if name == "COUNT":
        return len(values)
    if not values:
        return None
    if name in ("MIN", "MAX"):
        kinds = {_kind(v) for v in values}
        if len(kinds) > 1:
            raise QueryError(f"{name} cannot compare a {' with a '.join(sorted(kinds))}")
        return min(values) if name == "MIN" else max(values)
    for v in values:
        _check_number(v, name)
    try:
        total = sum(values)
        return total if name == "SUM" else total / len(values)
    except OverflowError:
        raise QueryError(f"numeric overflow in {name}") from None


# -- expression compilation -------------------------------------------------


def _contains_aggregate(node):
    return node.kind == "agg" or any(_contains_aggregate(a) for a in node.args)


def _check_no_nested_aggregates(node, inside=False):
    if node.kind == "agg":
        if inside:
            raise QueryError("aggregate functions cannot be nested")
        inside = True
    for a in node.args:
        _check_no_nested_aggregates(a, inside)


def _compile(node, leaf):
    """Compile ``node`` into a function of an evaluation context.

    ``leaf(node)`` handles context-dependent nodes (columns, aggregates, and
    in grouped queries GROUP BY expressions), returning a function or None.
    """
    f = leaf(node)
    if f is not None:
        return f
    kind, info, args = node
    if kind == "lit":
        value = info[1]
        return lambda ctx: value
    subs = [_compile(a, leaf) for a in args]

    if kind == "neg":
        (x,) = subs
        return lambda ctx: _negate(x(ctx))
    if kind == "arith":
        a, b = subs
        return lambda ctx: _arith(info, a(ctx), b(ctx))
    if kind == "concat":
        a, b = subs
        return lambda ctx: _concat(a(ctx), b(ctx))
    if kind == "cmp":
        a, b = subs
        return lambda ctx: _compare(info, a(ctx), b(ctx))
    if kind == "isnull":
        (x,) = subs
        return lambda ctx: (x(ctx) is None) != info
    if kind == "not":
        (x,) = subs
        return lambda ctx: _not(x(ctx))
    if kind == "and":
        a, b = subs

        def and_(ctx):
            left = a(ctx)
            _check_boolean(left, "AND")
            return False if left is False else _and(left, b(ctx))

        return and_
    if kind == "or":
        a, b = subs

        def or_(ctx):
            left = a(ctx)
            _check_boolean(left, "OR")
            if left is True:
                return True
            right = b(ctx)
            _check_boolean(right, "OR")
            if right is True:
                return True
            return None if left is None or right is None else False

        return or_
    if kind in ("in", "between", "like"):
        x, *rest = subs

        def test(ctx):
            value = x(ctx)
            if kind == "in":
                result = _in(value, [item(ctx) for item in rest])
            elif kind == "between":
                low, high = rest
                result = _and(_compare("<=", low(ctx), value), _compare("<=", value, high(ctx)))
            else:
                result = _like(value, rest[0](ctx))
            return _not(result) if info else result

        return test
    if kind == "func":
        if info == "COALESCE":

            def coalesce(ctx):
                for arg in subs:
                    value = arg(ctx)
                    if value is not None:
                        return value
                return None

            return coalesce
        fn = _FUNCTIONS[info]
        return lambda ctx: fn(*[arg(ctx) for arg in subs])
    raise AssertionError(f"unexpected node {node!r}")


def _row_leaf(node):
    """Leaf handler for expressions evaluated on a row tuple."""
    if node.kind == "col":
        return operator.itemgetter(node.info)
    if node.kind == "agg":
        raise QueryError("aggregate functions are not allowed here")
    return None


class _GroupLeaf:
    """Leaf handler for expressions evaluated on a group.

    A group context is ``(key_values, aggregate_values)``. Aggregates met
    while compiling are recorded in ``self.aggregates`` so they can be
    computed for each group.
    """

    def __init__(self, group_by, header):
        self.keys = {}
        for i, expr in enumerate(group_by):
            self.keys.setdefault(expr, i)
        self.header = header
        self.aggregates = {}

    def __call__(self, node):
        i = self.keys.get(node)
        if i is not None:
            return lambda ctx: ctx[0][i]
        if node.kind == "agg":
            j = self.aggregates.setdefault(node, len(self.aggregates))
            return lambda ctx: ctx[1][j]
        if node.kind == "col":
            raise QueryError(
                f"column {self.header[node.info]} must appear in GROUP BY "
                "or be used in an aggregate function"
            )
        return None


# -- execution --------------------------------------------------------------


def _column_map(header):
    columns = {}
    for i, name in enumerate(header):
        columns[name.lower()] = None if name.lower() in columns else i
    return columns


def _resolve(node, columns):
    """Replace ``name`` nodes with ``col`` nodes holding the column index."""
    if node.kind == "name":
        key = node.info.lower()
        if key not in columns:
            raise QueryError(f"unknown column {node.info}")
        if columns[key] is None:
            raise QueryError(f"ambiguous column name {node.info}")
        return Node("col", columns[key], ())
    if not node.args:
        return node
    return Node(node.kind, node.info, tuple(_resolve(a, columns) for a in node.args))


def execute(query, directory):
    header, rows = load_table(directory, query.table)
    columns = _column_map(header)

    def resolve(expr):
        if expr is None:
            return None
        expr = _resolve(expr, columns)
        _check_no_nested_aggregates(expr)
        return expr

    where = resolve(query.where)
    if where is not None and _contains_aggregate(where):
        raise QueryError("aggregate functions are not allowed in WHERE")
    group_by = [resolve(e) for e in query.group_by]
    if any(_contains_aggregate(e) for e in group_by):
        raise QueryError("aggregate functions are not allowed in GROUP BY")
    having = resolve(query.having)

    if query.columns is None:
        select = [Node("col", i, ()) for i in range(len(header))]
        names = list(header)
    else:
        select = [resolve(c.expr) for c in query.columns]
        names = [
            c.alias if c.alias is not None
            else header[expr.info] if c.bare_name is not None
            else c.text
            for c, expr in zip(query.columns, select)
        ]

    # Each ORDER BY item is ("out", output column index) or ("expr", node).
    lower_names = [n.lower() for n in names]
    order_by = []
    for item in query.order_by:
        if item.bare_name is not None and item.bare_name.lower() in lower_names:
            order_by.append(("out", lower_names.index(item.bare_name.lower())))
        elif item.position is not None:
            if not 1 <= item.position <= len(names):
                raise QueryError(f"ORDER BY position {item.position} is out of range")
            order_by.append(("out", item.position - 1))
        else:
            order_by.append(("expr", resolve(item.expr)))

    grouped = bool(group_by) or any(
        _contains_aggregate(e)
        for e in select + [having] + [ref for how, ref in order_by if how == "expr"]
        if e is not None
    )

    # Compile everything before touching the data, so errors in the query
    # are reported even when the table is empty.
    where_fn = _compile(where, _row_leaf) if where is not None else None
    if grouped:
        key_fns = [_compile(e, _row_leaf) for e in group_by]
        leaf = _GroupLeaf(group_by, header)
    else:
        leaf = _row_leaf
    select_fns = [_compile(e, leaf) for e in select]
    having_fn = _compile(having, leaf) if having is not None else None
    order_fns = [
        (lambda out, ctx, i=ref: out[i]) if how == "out"
        else (lambda out, ctx, f=_compile(ref, leaf): f(ctx))
        for how, ref in order_by
    ]

    if where_fn is not None:
        rows = [r for r in rows if _truth(where_fn(r), "WHERE")]

    if grouped:
        aggregate_fns = [
            (node.info, _compile(node.args[0], _row_leaf) if node.args else None)
            for node in leaf.aggregates
        ]
        if group_by:
            groups = {}
            for r in rows:
                values = tuple(f(r) for f in key_fns)
                key = tuple(map(_group_key, values))
                groups.setdefault(key, (values, []))[1].append(r)
            groups = list(groups.values())
        else:
            groups = [((), rows)]
        contexts = [
            (values, [_aggregate(name, arg, members) for name, arg in aggregate_fns])
            for values, members in groups
        ]
    else:
        contexts = rows

    if having_fn is not None:
        contexts = [c for c in contexts if _truth(having_fn(c), "HAVING")]

    results = [(tuple(f(c) for f in select_fns), c) for c in contexts]

    if query.distinct:
        seen = set()
        unique = []
        for out, ctx in results:
            key = tuple(map(_group_key, out))
            if key not in seen:
                seen.add(key)
                unique.append((out, ctx))
        results = unique

    if order_fns:
        keys = [[f(out, ctx) for f in order_fns] for out, ctx in results]
        for k in range(len(order_fns)):
            kinds = {_kind(row[k]) for row in keys if row[k] is not None}
            if len(kinds) > 1:
                raise QueryError(f"ORDER BY cannot compare a {' with a '.join(sorted(kinds))}")
        order = list(range(len(results)))
        # Stable sorts from the last key to the first give a multi-key sort;
        # NULLs sort lowest, so they come first ascending and last descending.
        for k in reversed(range(len(order_fns))):
            order.sort(
                key=lambda i: (keys[i][k] is not None, keys[i][k]),
                reverse=query.order_by[k].desc,
            )
        results = [results[i] for i in order]

    out_rows = [out for out, ctx in results]
    if query.offset is not None:
        out_rows = out_rows[query.offset :]
    if query.limit is not None:
        out_rows = out_rows[: query.limit]
    return Result(names, out_rows)

