import csv
import sys

from . import QueryError, run


def _format(value):
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    return value


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="python -m minisql",
        description="Run a SQL SELECT query against a directory of CSV files.",
    )
    parser.add_argument("query", help="the SELECT query to run")
    parser.add_argument(
        "--dir", default=".", help="directory containing the CSV files (default: .)"
    )
