            "SELECT id, age, score > 1 AS big FROM people WHERE id < 3", "--dir", self.dir
        )
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertEqual(proc.stdout, b"id,age,big\r\n1,30,true\r\n2,,\r\n")

    def test_error(self):
        proc = self.cli("SELECT nope FROM people", "--dir", self.dir)
        self.assertEqual(proc.returncode, 1)
        self.assertEqual(proc.stdout, b"")
